#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\n' > "$t"
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 09:00 10:30 x >/dev/null || { echo "book failed"; fail=1; }
grep -q '^# room' "$t" && grep -q '^aoi.2026-01-05.09:00.10:30.x$' "$t" || { echo "booking not appended"; fail=1; }
BOOKINGS=$t bash src/book.sh aoi 2026-01-05 10:00 11:00 y >/dev/null 2>&1; [ $? = 1 ] || { echo "overlap should exit 1"; fail=1; }
rm -f "$t"; exit $fail

spec/cancel.spec.sh.text:
#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\nkaede\t2026-01-05\t09:00\t10:00\tz\n' > "$t"
# not found: exit 1, message on stderr only, file unchanged
before=$(cat "$t")
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); rc=$?
err=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null)
[ "$rc" = 1 ] || { echo "not found should exit 1, got $rc"; fail=1; }
[ -z "$out" ] || { echo "not found should print nothing to stdout: $out"; fail=1; }
[ "$err" = 'not found: aoi 2026-01-05 11:00' ] || { echo "not found stderr: $err"; fail=1; }
[ "$(cat "$t")" = "$before" ] || { echo "not found should not change the file"; fail=1; }
# usage: exit 2, message on stderr only
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>/dev/null); rc=$?
err=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>&1 >/dev/null)
[ "$rc" = 2 ] || { echo "usage should exit 2, got $rc"; fail=1; }
[ -z "$out" ] || { echo "usage should print nothing to stdout: $out"; fail=1; }
[ "$err" = 'usage: cancel.sh ROOM DATE START' ] || { echo "usage stderr: $err"; fail=1; }
# cancel: match on room, date and start; only that row goes
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^kaede.2026-01-05.09:00' "$t" || { echo "kaede 09:00 booking was removed with aoi's"; fail=1; }
grep -q '^kaede.2026-01-05.13:00' "$t" || { echo "other booking was removed"; fail=1; }
grep -q '^# room.date.start.end.who$' "$t" || { echo "header line was removed"; fail=1; }
rm -f "$t"; exit $fail

