grep -q '^kaede.2026-01-05.13:00' "$t" || { echo "other row was removed"; fail=1; }
head -1 "$t" | grep -q '^# room' || { echo "header line was removed"; fail=1; }
err=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null); [ "$err" = 'not found: aoi 2026-01-05 11:00' ] || { echo "not found message: $err"; fail=1; }
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); [ -z "$out" ] || { echo "not found wrote stdout: $out"; fail=1; }
