src/cancel.sh.text:
#!/bin/bash
# cancel.sh ROOM DATE START: remove the one booking that matches room, date and start.
set -u
BOOKINGS=${BOOKINGS:-data/bookings.tsv}
[ $# -eq 3 ] || { echo "usage: cancel.sh ROOM DATE START" >&2; exit 2; }
room=$1 date=$2 start=$3
match='!/^#/ && $1 == r && $2 == d && $3 == s'
hit=$(awk -F'\t' -v r="$room" -v d="$date" -v s="$start" "$match" "$BOOKINGS" | head -1)
[ -n "$hit" ] || { echo "not found: $room $date $start" >&2; exit 1; }
tmp=$(mktemp "$BOOKINGS.XXXXXX")
awk -F'\t' -v r="$room" -v d="$date" -v s="$start" \
  '!done && !/^#/ && $1 == r && $2 == d && $3 == s { done = 1; next } { print }' "$BOOKINGS" > "$tmp" \
  && mv "$tmp" "$BOOKINGS" || { rm -f "$tmp"; exit 1; }
IFS=$'\t' read -r r d bs be bw <<< "$hit"
echo "cancelled: $r $d $bs-$be $bw"

