#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room' "$t" || { echo "header line removed"; fail=1; }
grep -q '^kaede.2026-01-05.13:00.14:00.y$' "$t" || { echo "other booking removed"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 >/dev/null 2>&1; [ $? = 1 ] || { echo "not found should exit 1"; fail=1; }
rm -f "$t"

# same date and start in another room must not be cancelled
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\ty\n' > "$t"
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00 >/dev/null || { echo "cancel (other room present) failed"; fail=1; }
grep -q '^kaede.2026-01-05.09:00.10:00.y$' "$t" || { echo "other room's booking removed"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "aoi booking still there"; fail=1; }
rm -f "$t"

# usage error: stdout empty, usage on stderr, exit 2
out=$(bash src/cancel.sh aoi 2026-01-05 2>/dev/null); rc=$?
[ "$rc" = 2 ] || { echo "wrong arg count should exit 2, got $rc"; fail=1; }
[ -z "$out" ] || { echo "usage printed to stdout: $out"; fail=1; }
exit $fail

