#!/bin/bash
fail=0
hdr=$(printf '# room\tdate\tstart\tend\twho')

t=$(mktemp); printf '%s\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' "$hdr" > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
exp=$(printf '%s\nkaede\t2026-01-05\t13:00\t14:00\ty' "$hdr")
[ "$(cat "$t")" = "$exp" ] || { echo "file after cancel: $(cat "$t")"; fail=1; }
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); rc=$?
[ $rc = 1 ] || { echo "not found should exit 1"; fail=1; }
[ -z "$out" ] || { echo "not found should print nothing on stdout: $out"; fail=1; }
[ "$(cat "$t")" = "$exp" ] || { echo "not found changed the file"; fail=1; }
rm -f "$t"

t=$(mktemp); printf '%s\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\ty\n' "$hdr" > "$t"
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00 >/dev/null || { echo "cancel same slot failed"; fail=1; }
exp=$(printf '%s\nkaede\t2026-01-05\t09:00\t10:00\ty' "$hdr")
[ "$(cat "$t")" = "$exp" ] || { echo "other room's booking removed: $(cat "$t")"; fail=1; }
rm -f "$t"

out=$(bash src/cancel.sh aoi 2026-01-05 2>/dev/null); rc=$?
[ $rc = 2 ] || { echo "usage should exit 2"; fail=1; }
[ -z "$out" ] || { echo "usage should print nothing on stdout: $out"; fail=1; }
bash src/cancel.sh aoi 2026-01-05 2>&1 >/dev/null | grep -qx 'usage: cancel.sh ROOM DATE START' || { echo "usage text missing on stderr"; fail=1; }
exit $fail

