#!/bin/bash
fail=0
t=$(mktemp); e=$(mktemp)
printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\ty\nkaede\t2026-01-05\t13:00\t14:00\tw\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room' "$t" || { echo "header line lost"; fail=1; }
grep -q '^kaede.2026-01-05.09:00.10:00.y$' "$t" || { echo "other room's booking at the same time was removed"; fail=1; }
grep -q '^kaede.2026-01-05.13:00.14:00.w$' "$t" || { echo "other booking was removed"; fail=1; }
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>"$e"); [ $? = 1 ] || { echo "not found should exit 1"; fail=1; }
[ -z "$out" ] && grep -q '^not found: aoi 2026-01-05 11:00$' "$e" || { echo "not found should print to stderr only"; fail=1; }
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>"$e"); [ $? = 2 ] || { echo "usage should exit 2"; fail=1; }
[ -z "$out" ] && grep -q '^usage: cancel.sh ROOM DATE START$' "$e" || { echo "usage should print to stderr only"; fail=1; }
rm -f "$t" "$e"; exit $fail

