#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t09:00\t10:00\tz\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"

# 取り消し: 一致した 1 件だけが消え、ヘッダと他の部屋の予約は残る
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
grep -q '^# room' "$t" || { echo "header row removed"; fail=1; }
grep -q '^kaede.2026-01-05.09:00.10:00.z$' "$t" || { echo "kaede 09:00 removed by aoi cancel"; fail=1; }
grep -q '^kaede.2026-01-05.13:00.14:00.y$' "$t" || { echo "kaede 13:00 changed by aoi cancel"; fail=1; }

# 部屋が違えば一致しない（kaede の 13:00 は aoi の 13:00 として扱わない）
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 13:00 >/dev/null 2>&1; [ $? = 1 ] || { echo "other room's booking matched"; fail=1; }
grep -q '^kaede.2026-01-05.13:00' "$t" || { echo "kaede booking removed by aoi cancel"; fail=1; }

# 一致が無い: exit 1、メッセージは stderr、stdout は空
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); rc=$?
[ $rc = 1 ] || { echo "not found should exit 1, got $rc"; fail=1; }
[ -z "$out" ] || { echo "not found should print nothing to stdout: $out"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null | grep -q '^not found: aoi 2026-01-05 11:00$' || { echo "not found message missing on stderr"; fail=1; }

# 使い方の誤り: exit 2、usage は stderr、stdout は空
