#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
[ "$(cat "$t")" = "$(printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t13:00\t14:00\ty')" ] || { echo "rows after cancel: $(cat "$t")"; fail=1; }
before=$(cat "$t")
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); rc=$?
[ $rc = 1 ] || { echo "not found should exit 1, got $rc"; fail=1; }
[ -z "$out" ] || { echo "not found should print nothing to stdout: $out"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null | grep -q '^not found: aoi 2026-01-05 11:00$' || { echo "not found message missing on stderr"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 13:00 >/dev/null 2>&1; [ $? = 1 ] || { echo "other room's booking at the same time should not match"; fail=1; }
[ "$(cat "$t")" = "$before" ] || { echo "file changed by a not-found cancel"; fail=1; }
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>/dev/null); rc=$?
[ $rc = 2 ] || { echo "usage should exit 2, got $rc"; fail=1; }
[ -z "$out" ] || { echo "usage should print nothing to stdout: $out"; fail=1; }
BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 2>&1 >/dev/null | grep -q '^usage: cancel.sh ROOM DATE START$' || { echo "usage message missing on stderr"; fail=1; }
rm -f "$t"; exit $fail

