#!/bin/bash
fail=0
t=$(mktemp); printf '# room\tdate\tstart\tend\twho\naoi\t2026-01-05\t09:00\t10:00\tx\nkaede\t2026-01-05\t13:00\t14:00\ty\n' > "$t"
out=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 09:00) || { echo "cancel failed"; fail=1; }
[ "$out" = 'cancelled: aoi 2026-01-05 09:00-10:00 x' ] || { echo "cancel output: $out"; fail=1; }
! grep -q '^aoi.2026-01-05.09:00' "$t" || { echo "booking still there"; fail=1; }
want=$(printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t13:00\t14:00\ty')
[ "$(cat "$t")" = "$want" ] || { echo "file after cancel: $(cat "$t")"; fail=1; }
o=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>/dev/null); rc=$?
[ $rc = 1 ] || { echo "not found should exit 1, got $rc"; fail=1; }
[ -z "$o" ] || { echo "not found should print nothing to stdout: $o"; fail=1; }
e=$(BOOKINGS=$t bash src/cancel.sh aoi 2026-01-05 11:00 2>&1 >/dev/null)
[ "$e" = 'not found: aoi 2026-01-05 11:00' ] || { echo "not found message: $e"; fail=1; }
o=$(bash src/cancel.sh aoi 2026-01-05 2>/dev/null); rc=$?
[ $rc = 2 ] || { echo "usage should exit 2, got $rc"; fail=1; }
[ -z "$o" ] || { echo "usage should print nothing to stdout: $o"; fail=1; }
e=$(bash src/cancel.sh aoi 2026-01-05 2>&1 >/dev/null)
[ "$e" = 'usage: cancel.sh ROOM DATE START' ] || { echo "usage message: $e"; fail=1; }
t2=$(mktemp); printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t09:00\t10:00\ty\naoi\t2026-01-05\t09:00\t10:00\tx\n' > "$t2"
BOOKINGS=$t2 bash src/cancel.sh aoi 2026-01-05 09:00 >/dev/null || { echo "cancel same time other room failed"; fail=1; }
want=$(printf '# room\tdate\tstart\tend\twho\nkaede\t2026-01-05\t09:00\t10:00\ty')
[ "$(cat "$t2")" = "$want" ] || { echo "other room booking removed: $(cat "$t2")"; fail=1; }
rm -f "$t" "$t2"; exit $fail

